operation.add:
        // === Embedded Multilang (Admin language correct detection) ===

        $admin_lang = $this->config->get('config_admin_language');

        // English default
        $data['text_backup_last'] = 'Last backup:';
        $data['text_backup_size'] = 'Size:';
        $data['text_backup_next'] = 'Next:';
        $data['text_backup_none'] = '—';

        // Romanian override
        if (strpos($admin_lang, 'ro') === 0) {
            $data['text_backup_last'] = 'Ultimul backup:';
            $data['text_backup_size'] = 'Dimensiune:';
            $data['text_backup_next'] = 'Următorul:';
            $data['text_backup_none'] = '—';
        }

        // Backup info logic (unchanged)
        $storage = defined('DIR_STORAGE') ? DIR_STORAGE : dirname(DIR_SYSTEM) . '/storage/';
        $path = $storage . 'backup/';

        $files = glob($path . '*');

        $data['last_backup_info'] = $data['text_backup_none'];
        $data['last_backup_size'] = $data['text_backup_none'];
        $data['next_backup_info'] = $data['text_backup_none'];

        $freq = 'daily';

        if ($files) {
            rsort($files);
            $file = $files[0];

            $mtime = filemtime($file);
            $data['last_backup_info'] = date("d.m.Y H:i", $mtime);
            $data['last_backup_size'] = round(filesize($file)/1024/1024, 2) . ' MB';

            if ($freq == 'daily') {
                $data['next_backup_info'] = date("d.m.Y H:i", strtotime("+1 day", $mtime));
            } elseif ($freq == 'weekly') {
                $data['next_backup_info'] = date("d.m.Y H:i", strtotime("+1 week", $mtime));
            } else {
                $data['next_backup_info'] = date("d.m.Y H:i", strtotime("+1 month", $mtime));
            }
        }

        $data['bluecart_backup_url'] = $this->url->link(
            'extension/module/bluecart_db_backup',
            'user_token=' . $this->session->data['user_token'],
            true
        );
